CREATE TABLE `User` (
 `id` VARCHAR(30) NOT NULL, `role` ENUM('RIDER','ADMIN','CUSTOMER') NOT NULL, `name` VARCHAR(100) NOT NULL, `phone` VARCHAR(20) NOT NULL, `email` VARCHAR(190) NULL, `passwordHash` VARCHAR(255) NOT NULL, `refreshTokenHash` VARCHAR(255) NULL, `tokenVersion` INTEGER NOT NULL DEFAULT 0, `createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), `updatedAt` DATETIME(3) NOT NULL,
 UNIQUE INDEX `User_phone_key` (`phone`), UNIQUE INDEX `User_email_key` (`email`), INDEX `User_role_createdAt_idx` (`role`,`createdAt`), PRIMARY KEY (`id`)
) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `Rider` (`userId` VARCHAR(30) NOT NULL, `vehicleNo` VARCHAR(20) NULL, `city` VARCHAR(80) NULL, `upiId` VARCHAR(100) NULL, `status` ENUM('PENDING','ACTIVE','BLOCKED') NOT NULL DEFAULT 'PENDING', `deletedAt` DATETIME(3) NULL, INDEX `Rider_status_city_idx` (`status`,`city`), PRIMARY KEY (`userId`), CONSTRAINT `Rider_userId_fkey` FOREIGN KEY (`userId`) REFERENCES `User` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `Customer` (`id` VARCHAR(30) NOT NULL, `name` VARCHAR(100) NOT NULL, `phone` VARCHAR(20) NOT NULL, `email` VARCHAR(190) NOT NULL, `company` VARCHAR(120) NULL, `passwordHash` VARCHAR(255) NOT NULL, `refreshTokenHash` VARCHAR(255) NULL, `tokenVersion` INTEGER NOT NULL DEFAULT 0, `createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), `updatedAt` DATETIME(3) NOT NULL, UNIQUE INDEX `Customer_email_key` (`email`), INDEX `Customer_phone_idx` (`phone`), PRIMARY KEY (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `AdPlan` (`id` VARCHAR(30) NOT NULL, `name` VARCHAR(80) NOT NULL, `description` TEXT NULL, `durationDays` INTEGER NOT NULL, `ridersCount` INTEGER NOT NULL, `pricePaise` BIGINT NOT NULL, `ratePerKmPaise` INTEGER NOT NULL DEFAULT 200, `active` BOOLEAN NOT NULL DEFAULT true, `deletedAt` DATETIME(3) NULL, `createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), `updatedAt` DATETIME(3) NOT NULL, INDEX `AdPlan_active_deletedAt_idx` (`active`,`deletedAt`), PRIMARY KEY (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `Order` (`id` VARCHAR(30) NOT NULL, `customerId` VARCHAR(30) NOT NULL, `planId` VARCHAR(30) NOT NULL, `amountPaise` BIGINT NOT NULL, `currency` VARCHAR(3) NOT NULL DEFAULT 'INR', `razorpayOrderId` VARCHAR(80) NULL, `razorpayPaymentId` VARCHAR(80) NULL, `status` ENUM('CREATED','PAID','FAILED','REFUND_PENDING','REFUNDED') NOT NULL DEFAULT 'CREATED', `idempotencyKey` VARCHAR(100) NULL, `failureReason` VARCHAR(255) NULL, `createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), `updatedAt` DATETIME(3) NOT NULL, UNIQUE INDEX `Order_razorpayOrderId_key` (`razorpayOrderId`), UNIQUE INDEX `Order_razorpayPaymentId_key` (`razorpayPaymentId`), UNIQUE INDEX `Order_idempotencyKey_key` (`idempotencyKey`), INDEX `Order_customerId_createdAt_idx` (`customerId`,`createdAt`), INDEX `Order_status_createdAt_idx` (`status`,`createdAt`), PRIMARY KEY (`id`), CONSTRAINT `Order_customerId_fkey` FOREIGN KEY (`customerId`) REFERENCES `Customer` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE, CONSTRAINT `Order_planId_fkey` FOREIGN KEY (`planId`) REFERENCES `AdPlan` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `Ad` (`id` VARCHAR(30) NOT NULL, `customerId` VARCHAR(30) NOT NULL, `orderId` VARCHAR(30) NOT NULL, `planId` VARCHAR(30) NOT NULL, `title` VARCHAR(150) NULL, `creativeUrl` VARCHAR(500) NULL, `creativePublicId` VARCHAR(255) NULL, `status` ENUM('PENDING_APPROVAL','APPROVED','RUNNING','COMPLETED','REJECTED') NOT NULL DEFAULT 'PENDING_APPROVAL', `startDate` DATE NULL, `endDate` DATE NULL, `rejectionReason` VARCHAR(255) NULL, `createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), `updatedAt` DATETIME(3) NOT NULL, UNIQUE INDEX `Ad_orderId_key` (`orderId`), INDEX `Ad_status_createdAt_idx` (`status`,`createdAt`), INDEX `Ad_customerId_createdAt_idx` (`customerId`,`createdAt`), INDEX `Ad_endDate_status_idx` (`endDate`,`status`), PRIMARY KEY (`id`), CONSTRAINT `Ad_customerId_fkey` FOREIGN KEY (`customerId`) REFERENCES `Customer` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE, CONSTRAINT `Ad_orderId_fkey` FOREIGN KEY (`orderId`) REFERENCES `Order` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE, CONSTRAINT `Ad_planId_fkey` FOREIGN KEY (`planId`) REFERENCES `AdPlan` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `AdAssignment` (`id` VARCHAR(30) NOT NULL, `adId` VARCHAR(30) NOT NULL, `riderId` VARCHAR(30) NOT NULL, `assignedAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), `status` ENUM('ACTIVE','REMOVED','COMPLETED') NOT NULL DEFAULT 'ACTIVE', UNIQUE INDEX `AdAssignment_adId_riderId_key` (`adId`,`riderId`), INDEX `AdAssignment_riderId_status_idx` (`riderId`,`status`), INDEX `AdAssignment_adId_status_idx` (`adId`,`status`), PRIMARY KEY (`id`), CONSTRAINT `AdAssignment_adId_fkey` FOREIGN KEY (`adId`) REFERENCES `Ad` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE, CONSTRAINT `AdAssignment_riderId_fkey` FOREIGN KEY (`riderId`) REFERENCES `User` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `DailyLog` (`id` VARCHAR(30) NOT NULL, `riderId` VARCHAR(30) NOT NULL, `adId` VARCHAR(30) NOT NULL, `logDate` DATE NOT NULL, `startKm` DECIMAL(9,1) NOT NULL, `endKm` DECIMAL(9,1) NULL, `startPhotoUrl` VARCHAR(500) NOT NULL, `startPhotoPublicId` VARCHAR(255) NULL, `endPhotoUrl` VARCHAR(500) NULL, `endPhotoPublicId` VARCHAR(255) NULL, `adPhotoUrl` VARCHAR(500) NULL, `adPhotoPublicId` VARCHAR(255) NULL, `status` ENUM('SUBMITTED','VERIFIED','REJECTED') NOT NULL DEFAULT 'SUBMITTED', `adminNote` VARCHAR(255) NULL, `suspicious` BOOLEAN NOT NULL DEFAULT false, `suspiciousReason` VARCHAR(255) NULL, `createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), `updatedAt` DATETIME(3) NOT NULL, UNIQUE INDEX `DailyLog_riderId_adId_logDate_key` (`riderId`,`adId`,`logDate`), INDEX `DailyLog_status_logDate_idx` (`status`,`logDate`), INDEX `DailyLog_riderId_logDate_idx` (`riderId`,`logDate`), INDEX `DailyLog_adId_logDate_idx` (`adId`,`logDate`), PRIMARY KEY (`id`), CONSTRAINT `DailyLog_riderId_fkey` FOREIGN KEY (`riderId`) REFERENCES `User` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE, CONSTRAINT `DailyLog_adId_fkey` FOREIGN KEY (`adId`) REFERENCES `Ad` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `Location` (`id` BIGINT NOT NULL AUTO_INCREMENT, `riderId` VARCHAR(30) NOT NULL, `lat` DECIMAL(9,6) NOT NULL, `lng` DECIMAL(9,6) NOT NULL, `recordedAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), INDEX `Location_riderId_recordedAt_idx` (`riderId`,`recordedAt`), INDEX `Location_recordedAt_idx` (`recordedAt`), PRIMARY KEY (`id`), CONSTRAINT `Location_riderId_fkey` FOREIGN KEY (`riderId`) REFERENCES `User` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `Payout` (`id` VARCHAR(30) NOT NULL, `riderId` VARCHAR(30) NOT NULL, `periodStart` DATE NOT NULL, `periodEnd` DATE NOT NULL, `totalKm` DECIMAL(10,1) NOT NULL, `ratePerKmPaise` INTEGER NOT NULL, `amountPaise` BIGINT NOT NULL, `status` ENUM('PENDING','PAID') NOT NULL DEFAULT 'PENDING', `paidAt` DATETIME(3) NULL, `reference` VARCHAR(100) NULL, `createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), UNIQUE INDEX `Payout_riderId_periodStart_periodEnd_key` (`riderId`,`periodStart`,`periodEnd`), INDEX `Payout_status_periodEnd_idx` (`status`,`periodEnd`), PRIMARY KEY (`id`), CONSTRAINT `Payout_riderId_fkey` FOREIGN KEY (`riderId`) REFERENCES `User` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `WebhookEvent` (`id` VARCHAR(30) NOT NULL, `eventId` VARCHAR(100) NOT NULL, `eventType` VARCHAR(100) NOT NULL, `payload` JSON NOT NULL, `processedAt` DATETIME(3) NULL, `attempts` INTEGER NOT NULL DEFAULT 0, `lastError` VARCHAR(500) NULL, `createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), UNIQUE INDEX `WebhookEvent_eventId_key` (`eventId`), INDEX `WebhookEvent_processedAt_createdAt_idx` (`processedAt`,`createdAt`), PRIMARY KEY (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `AuditLog` (`id` VARCHAR(30) NOT NULL, `actorId` VARCHAR(30) NOT NULL, `action` VARCHAR(80) NOT NULL, `entityType` VARCHAR(80) NOT NULL, `entityId` VARCHAR(50) NOT NULL, `metadata` JSON NULL, `requestId` VARCHAR(100) NULL, `createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), INDEX `AuditLog_actorId_createdAt_idx` (`actorId`,`createdAt`), INDEX `AuditLog_entityType_entityId_createdAt_idx` (`entityType`,`entityId`,`createdAt`), PRIMARY KEY (`id`), CONSTRAINT `AuditLog_actorId_fkey` FOREIGN KEY (`actorId`) REFERENCES `User` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
